1 KONSTRUKTOR (od Spring 4.3):
  class Service { Service(Dep dep) {...} }  -- BEZ @Autowired, dziala automatycznie

WIELE KONSTRUKTOROW:
  class Service {
      @Autowired Service(Dep dep) {...}       -- Spring UZYWA tego
      Service(Dep dep, Extra extra) {...}     -- Spring IGNORUJE (brak @Autowired)
  }
  -- BEZ @Autowired na ktoryms z nich: BeanCreationException (Spring NIE zgaduje)

@Service
class ImplicitInjectionOrderService {
    private final PriceCalculator calculator;

    // BEZ @Autowired - dziala, bo to JEDYNY konstruktor (Spring 4.3+)
    ImplicitInjectionOrderService(PriceCalculator calculator) {
        this.calculator = calculator;
    }
}

@Service
class ExplicitMultiConstructorService {
    private final PriceCalculator calculator;
    private final Logger logger;

    @Autowired // WYMAGANE - jest wiecej niz 1 konstruktor
    ExplicitMultiConstructorService(PriceCalculator calculator) {
        this.calculator = calculator;
        this.logger = Logger.getGlobal();
    }

    ExplicitMultiConstructorService(PriceCalculator calculator, Logger logger) { // POMOCNICZY
        this.calculator = calculator; // Spring GO IGNORUJE - dla recznego uzycia (np. w testach)
        this.logger = logger;
    }
}
